(function(E){ const x = E["ai-m1"] = E["ai-m1"] || {units:{}}; x.units["ai-1"] = {"grammar":{"id":"c-ai-1-g","level":"B1","course":"ai-internet","unit":"ai-1","title":"Recommending a tool: good at, better for, if you need","titleTr":"Araç önermek: good at, better for, if you need","titleFa":"ابزار را پیشنهاد بده: good at، better for، if you need","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["X is good at + -ing","Claude is good at answering questions about long documents."],["X is better for + noun","Perplexity is better for quick research."],["X works inside + place","Copilot works inside Word and Excel."],["If you need X, try Y","If you need sources, try Perplexity."]]},"wrong":"ChatGPT is good at write emails.","right":"ChatGPT is good at writing emails.","blank":{"sentence":"Gemini is good at ___ long topics.","word":"summarising","distractors":["summarise","to summarise"]},"wrong2":"If you will need links, try Perplexity.","right2":"If you need links, try Perplexity.","blank2":{"sentence":"If you ___ pictures, try an image maker.","word":"need","distractors":["will need","needing"]},"expParts":{"tryFrom":"blank","rule":[{"en":"After good at, use a verb with -ing.","tr":"good at'ten sonra -ing'li fiil kullan.","fa":"بعد از good at فعل با ‎-ing بیاور.","ex":"It is good at rewriting emails."},{"en":"After better for, use a noun or -ing.","tr":"better for'dan sonra isim ya da -ing'li fiil gelir.","fa":"بعد از better for اسم یا فعل با ‎-ing می‌آید.","ex":"It is better for research."},{"en":"Use if + present, then try.","tr":"if + geniş zaman, ardından try kullan.","fa":"بعد از if فعل را در زمان حال بیاور و در بخش دوم از try استفاده کن.","ex":"If you need pictures, try Midjourney."}],"test":{"en":"Does a verb follow good at? It needs -ing.","tr":"good at'ten sonra fiil mi geliyor? -ing alması gerekir.","fa":"بعد از good at فعل آمده؟ باید ‎-ing بگیرد."}},"errorWatch":[{"find":["good at write","good at make","good at answer"],"fix":{"en":"After good at, use -ing: \"good at writing\".","tr":"good at'ten sonra -ing kullan: \"good at writing\".","fa":"بعد از good at از ‎-ing استفاده کن: «good at writing»."}}]},"b2":{"id":"c-ai-1-b2","level":"B2","course":"ai-internet","unit":"ai-1","track":"B2","title":"Giving a reason: since, as, which means","titleTr":"Neden belirtmek: since, as, which means","titleFa":"دلیل آوردن: since، as، which means","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["since + reason","Since our files are in Word, I suggest Copilot."],["which means + result","It gives links, which means we can check them."]]},"wrong":"It gives links which mean we can check them.","right":"It gives links, which means we can check them.","blank":{"sentence":"___ we work in Gmail, I suggest Gemini.","word":"Since","distractors":["So","Which"]},"wrong2":"Since our files are in Word, so I suggest Copilot.","right2":"Since our files are in Word, I suggest Copilot.","blank2":{"sentence":"It has a free plan, ___ we can try it.","word":"which means","distractors":["since means","as means"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Since or as can open the sentence with the reason.","tr":"since ya da as cümleyi nedenle açabilir.","fa":"با since یا as می‌توانی جمله را با دلیل شروع کنی.","ex":"As we use Gmail, Gemini fits."},{"en":"Which means adds the result of the whole idea.","tr":"which means tüm fikrin sonucunu ekler.","fa":"با which means نتیجه‌ی کل حرفت را اضافه می‌کنی.","ex":"It is paid, which means we need a budget."},{"en":"Use a comma before which means.","tr":"which means'ten önce virgül kullan.","fa":"پیش از which means ویرگول بگذار.","ex":"It lives in Word, which means no copying."}],"test":{"en":"Can you put \"and so\" there? Then which means fits.","tr":"Oraya \"and so\" koyabiliyor musun? O zaman which means uyar.","fa":"می‌توانی آنجا «and so» بگذاری؟ پس which means مناسب است."}},"errorWatch":[{"find":["since our files are in word, so"],"fix":{"en":"Don't use so after since.","tr":"since'ten sonra so kullanma.","fa":"بعد از since دیگر so نیاور."}}],"useIn":{"en":"B2: give the reason for your recommendation with since or which means.","tr":"B2: önerinin nedenini since ya da which means ile ver.","fa":"B2: دلیل پیشنهادت را با since یا which means بگو."},"exitItem":{"from":"ai-1","kind":"blank","prompt":"___ the sources matter here, I would start with AI search.","options":["Since","Which means","So"],"correct":0}},"vocab":{"id":"c-ai-1-v","level":"B1","category":"vocab","course":"ai-internet","unit":"ai-1","goals":["career"],"title":{"en":"Talking about tools","tr":"Araçlar hakkında konuşmak","fa":"حرف زدن درباره‌ی ابزارها"},"cards":[{"word":"assistant","sentence":"A text assistant answers in a chat.","meaning":{"en":"An AI tool that writes and answers in a chat.","tr":"Sohbette yazan ve yanıt veren yapay zekâ aracı.","fa":"ابزار هوش مصنوعی که در چت می‌نویسد و جواب می‌دهد."}},{"word":"image maker","sentence":"We used an image maker for the poster.","meaning":{"en":"A tool that makes pictures from words.","tr":"Kelimelerden görsel üreten araç.","fa":"ابزاری که از روی کلمه‌ها تصویر می‌سازد."}},{"word":"paid plan","sentence":"Midjourney needs a paid plan.","meaning":{"en":"A subscription you pay for.","tr":"Ücretli abonelik.","fa":"اشتراکی که برایش پول می‌دهی."}},{"word":"available","sentence":"This tool is not available in every country.","meaning":{"en":"Offered and possible to use.","tr":"Sunulan, kullanılabilen.","fa":"قابل استفاده، در دسترس."}},{"word":"draft","sentence":"The tool wrote a first draft.","meaning":{"en":"A first version of a text.","tr":"Bir metnin ilk hâli.","fa":"نسخه‌ی اول یک متن."}},{"word":"source","sentence":"Open the source and read it.","meaning":{"en":"The place where a fact comes from.","tr":"Bir bilginin geldiği yer.","fa":"جایی که یک مطلب از آن آمده."}}]},"judge":{"id":"c-ai-1-j","course":"ai-internet","unit":"ai-1","type":"judge","title":{"en":"Which tool fits this job?","tr":"Bu işe hangi araç uyar?","fa":"کدام ابزار به این کار می‌خورد؟"},"prompt":"Read each job and its suggestion. Choose what the suggestion does well.","parts":["Fits the job","Gives a reason"],"instruction":{"en":"Tap what each line does well. A good recommendation has both.","tr":"Her satırın iyi yaptığı şeye dokun. İyi bir öneride ikisi de olur.","fa":"روی چیزی که هر خط خوب انجام داده بزن. یک پیشنهاد خوب هر دو را دارد."},"items":[{"by":"Example answer","prompt":"Job: find three sources on a new law.","answer":"Try Perplexity.","present":["Fits the job"],"fix":{"en":"It fits, but there is no reason. Add one: \"It gives links we can open.\"","tr":"Uyuyor ama neden yok. Ekle: \"It gives links we can open.\"","fa":"مناسب است، ولی دلیل ندارد. اضافه کن: «It gives links we can open.»"}},{"by":"Example answer","prompt":"Job: make a poster picture.","answer":"Try Copilot because it works inside Word.","present":["Gives a reason"],"fix":{"en":"The reason is true, but it doesn't help with a poster picture. Suggest an image maker.","tr":"Neden doğru ama afiş görseline yardımcı olmuyor. Görsel üretici öner.","fa":"دلیل درست است، ولی به تصویر پوستر کمکی نمی‌کند. سازنده‌ی تصویر را پیشنهاد بده."}},{"by":"Good model","prompt":"Job: summarise an email thread in Outlook.","answer":"If you work in Outlook, try Copilot. It works inside the program.","present":["Fits the job","Gives a reason"],"fix":null},{"by":"Example answer","prompt":"Job: write a difficult email.","answer":"Everyone says this tool is the best.","present":[],"fix":{"en":"It gives no fit and no real reason. \"Everyone says\" is not a reason.","tr":"Ne uygunluk var ne gerçek bir neden. \"Everyone says\" bir neden değildir.","fa":"نه مناسب است نه دلیل واقعی دارد. «Everyone says» دلیل نیست."}}]},"speaking":{"id":"ai-1","course":"ai-internet","unit":"ai-1","topic":{"en":"Recommend a tool to a colleague","tr":"Bir meslektaşına araç öner","fa":"یک ابزار را به همکارت پیشنهاد بده"},"warmup":{"en":"Which AI tools have you heard of at work?","tr":"İş yerinde hangi yapay zekâ araçlarını duydun?","fa":"در محل کار اسم کدام ابزارهای هوش مصنوعی را شنیده‌ای؟"},"questions":[{"en":"A colleague asks: \"Which tool should I use for long emails?\" Answer.","tr":"Bir meslektaşın soruyor: \"Which tool should I use for long emails?\" Yanıtla.","fa":"همکارت می‌پرسد: «Which tool should I use for long emails?» جواب بده."},{"en":"A colleague says: \"It sounded so sure, so it must be right.\" Explain why not.","tr":"Bir meslektaşın diyor ki: \"It sounded so sure, so it must be right.\" Neden öyle olmadığını açıkla.","fa":"همکارت می‌گوید: «It sounded so sure, so it must be right.» توضیح بده چرا این‌طور نیست."},{"en":"Say one thing the tool is not the best for.","tr":"Aracın en iyi olmadığı bir işi söyle.","fa":"یک کار را بگو که این ابزار برایش بهترین نیست."}],"followups":[{"en":"Now say it again about your own work. Use made-up names and numbers.","tr":"Şimdi aynısını kendi işin için söyle. Uydurma ad ve sayılar kullan.","fa":"حالا همین را درباره‌ی کار خودت بگو. از نام‌ها و عددهای ساختگی استفاده کن."}],"expressions":[{"phrase":"I suggest...","meaning":{"en":"Gives a recommendation politely.","tr":"Nazikçe öneride bulunur.","fa":"مؤدبانه پیشنهاد می‌دهد."}},{"phrase":"It's good at...","meaning":{"en":"Says what a tool does well.","tr":"Aracın iyi yaptığı şeyi söyler.","fa":"می‌گوید ابزار چه کاری را خوب انجام می‌دهد."}},{"phrase":"It's not the best for...","meaning":{"en":"Says an honest limit.","tr":"Dürüst bir sınır söyler.","fa":"یک محدودیت واقعی را می‌گوید."}},{"phrase":"It writes likely words, so...","meaning":{"en":"Explains why a tool can be wrong.","tr":"Aracın neden yanılabileceğini açıklar.","fa":"توضیح می‌دهد چرا ابزار ممکن است اشتباه کند."}}],"model":"If your emails are long, I suggest a text assistant. If you work in Outlook, try Copilot, because it works inside the program. It's good at summarising a thread, so you can read the main points first. It's not the best for facts you won't check. It writes likely words, so a sure tone isn't proof. Read the names and dates yourself.","selfCheck":[{"en":"I did every point of the task.","tr":"Görevin her noktasını yaptım.","fa":"همه‌ی نکته‌های تمرین را انجام دادم."},{"en":"I used at least two phrases from this lesson.","tr":"Bu dersten en az iki ifade kullandım.","fa":"دست‌کم دو عبارت از این درس به کار بردم."},{"en":"I spoke in short, clear sentences.","tr":"Kısa ve net cümlelerle konuştum.","fa":"با جمله‌های کوتاه و روشن حرف زدم."},{"en":"I named one limit of the tool.","tr":"Aracın bir sınırını söyledim.","fa":"یک محدودیت ابزار را گفتم."}]},"writing":{"id":"c-ai-1-w","title":{"en":"Your tool map","tr":"Araç haritan","fa":"نقشه‌ی ابزارهای تو"},"course":"ai-internet","unit":"ai-1","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"ai-final-5","prompt":{"en":"List six jobs from your own work. Next to each one, write the kind of tool or a tool name. Then write two sentences that recommend one tool to a colleague. No list of your own? Use these: reply to customer emails, summarise long threads, check a supplier claim, make a poster, rewrite a report, find a standard.","tr":"Kendi işinden altı iş yaz. Her birinin yanına araç türünü ya da bir araç adını yaz. Sonra bir meslektaşına bir aracı öneren iki cümle yaz. Kendi listen yok mu? Şunları kullan: reply to customer emails, summarise long threads, check a supplier claim, make a poster, rewrite a report, find a standard.","fa":"شش کار از شغل خودت بنویس. کنار هر کدام نوع ابزار یا نام یک ابزار را بنویس. بعد در دو جمله یک ابزار را به همکارت پیشنهاد بده. اگر فهرستی نداری، از این‌ها استفاده کن: reply to customer emails, summarise long threads, check a supplier claim, make a poster, rewrite a report, find a standard."},"model":"Reply to customer emails: text assistant. Summarise long threads: Copilot. Check a supplier claim: AI search. Make a poster: image maker. Rewrite a report: text assistant. Find a standard: AI search.\n\nIf you work in Outlook, try Copilot. It is good at summarising long threads, but you still check the names and dates.","frame":"___: ___.\n___: ___.\n___: ___.\n___: ___.\n___: ___.\n___: ___.\n\nIf you ___, try ___. It is good at ___.","words":[{"word":"good at"},{"word":"try"}],"minWords":30,"minSentences":2,"rubric":["Task done: every point of the task is there","Organised: clear parts, in a sensible order","Language: the phrases of this lesson, used correctly","Tone: clear and honest; nothing you cannot explain"],"rubricI18n":{"tr":["Görev: görevin her noktası var","Düzen: açık bölümler, mantıklı sıra","Dil: bu dersin ifadeleri, doğru kullanılmış","Üslup: açık ve dürüst; açıklayamayacağın bir şey yok"],"fa":["کامل بودن کار: همه‌ی نکته‌های تمرین آمده","نظم: بخش‌های روشن، با ترتیب منطقی","زبان: عبارت‌های این درس، درست به کار رفته","لحن: روشن و صادق؛ چیزی که نتوانی توضیح بدهی در آن نیست"]},"b2Task":{"en":"B2 track: no frame. Give the reason with since or which means, and name one limit.","tr":"B2 yolu: hazır çerçeve yok. Nedeni since ya da which means ile ver ve bir sınır söyle.","fa":"مسیر B2: چارچوب آماده نداری. دلیل را با since یا which means بگو و یک محدودیت را هم بنویس."},"own":{"en":"Use your real jobs, but no private details.","tr":"Gerçek işlerini kullan ama özel ayrıntı yazma.","fa":"از کارهای واقعی‌ات استفاده کن، ولی جزئیات خصوصی ننویس."},"routes":[{"t":{"en":"I use an AI tool","tr":"Bir yapay zekâ aracı kullanıyorum","fa":"از یک ابزار هوش مصنوعی استفاده می‌کنم"},"s":{"en":"Try one job on two tools if you can, then write which you would recommend.","tr":"Yapabiliyorsan bir işi iki araçta dene, sonra hangisini önereceğini yaz.","fa":"اگر می‌توانی یک کار را در دو ابزار امتحان کن و بنویس کدام را پیشنهاد می‌کنی."}},{"t":{"en":"I don't have a tool","tr":"Bir aracım yok","fa":"ابزاری ندارم"},"s":{"en":"Choose from the lines in this lesson. You don't need to open any tool.","tr":"Bu dersteki satırlardan seç. Hiçbir aracı açman gerekmez.","fa":"از توضیح‌های همین درس انتخاب کن. لازم نیست هیچ ابزاری را باز کنی."},"noTool":true}]},"exit":{"id":"c-ai-1-x","course":"ai-internet","unit":"ai-1","type":"exit","items":[{"from":"ai-1","kind":"mcq","prompt":"Why can a wrong answer come in perfect English?","options":["It searches only very old web pages.","It writes likely words and may not check facts.","It copies the answer of the last person."],"correct":1,"why":{"en":"Good words are not checked facts.","tr":"İyi kelimeler kontrol edilmiş bilgi değildir.","fa":"انگلیسی خوب به این معنی نیست که واقعیت‌ها بررسی شده‌اند."},"point":2},{"from":"ai-1","kind":"mcq","prompt":"You ask about a small local supplier and give no document. Why is the risk high?","options":["Prices can't be written in a prompt.","Few texts mention it, so it may guess.","Small firms block AI tools by law."],"correct":1,"why":{"en":"Tools guess most easily on rare facts. Give the facts yourself.","tr":"Araçlar en kolay nadir bilgilerde tahmin eder. Bilgiyi kendin ver.","fa":"ابزارها بیشتر درباره‌ی چیزهای کمیاب حدس می‌زنند، پس اطلاعات را خودت بده."},"point":2},{"from":"ai-1","kind":"mcq","prompt":"What makes an invented answer less likely?","options":["Give your facts and say \"use only these\".","Add please and thanks to your prompt.","Write your prompt in capital letters."],"correct":0,"why":{"en":"It has real text to use. You still check.","tr":"Kullanacak gerçek bir metni olur. Yine de kontrol edersin.","fa":"این‌طوری ابزار متن واقعی در دست دارد، ولی باز هم باید جوابش را بررسی کنی."},"point":2},{"from":"ai-1","kind":"mcq","prompt":"Which is an example of AI search?","options":["Perplexity","Midjourney","Word"],"correct":0,"why":{"en":"It answers with numbered links to sources.","tr":"Kaynaklara numaralı bağlantılarla yanıt verir.","fa":"با لینک‌های شماره‌دار به منبع‌ها جواب می‌دهد."},"point":3},{"from":"ai-1","kind":"mcq","prompt":"All your work is in Word and Excel. Where should you look first?","options":["Perplexity","Copilot","Midjourney"],"correct":1,"why":{"en":"Copilot works inside Microsoft programs.","tr":"Copilot, Microsoft programlarının içinde çalışır.","fa":"Copilot داخل برنامه‌های مایکروسافت کار می‌کند."},"point":4},{"from":"ai-1","kind":"blank","prompt":"This tool is good at ___ long reports.","options":["to read","read","reading"],"correct":2,"why":{"en":"After good at, use -ing.","tr":"good at'ten sonra -ing kullan.","fa":"بعد از good at از ‎-ing استفاده کن."},"point":5},{"from":"ai-1","kind":"blank","prompt":"If you ___ links to sources, try AI search.","options":["needing","need","will need"],"correct":1,"why":{"en":"After if, use the present.","tr":"if'ten sonra geniş zaman kullan.","fa":"بعد از if زمان حال بیاور."},"point":5},{"from":"ai-1","kind":"mcq","prompt":"Which is a real reason to choose a tool?","options":["It has a friendly, easy name.","It works inside the program I use.","Everyone at work talks about it."],"correct":1,"why":{"en":"Choose by the job and by where your work is.","tr":"İşe ve işinin bulunduğu yere göre seç.","fa":"ببین چه کاری داری و کارت کجاست، بعد انتخاب کن."},"point":4}]},"explain":{"id":"c-ai-1-e","course":"ai-internet","unit":"ai-1","type":"explain","level":"B1","title":{"en":"How AI tools work, and which to use","tr":"Yapay zekâ araçları nasıl çalışır, hangisi kullanılır","fa":"ابزارهای هوش مصنوعی چطور کار می‌کنند و از کدام استفاده کنی"},"objective":{"en":"In this lesson you will learn to explain why an AI tool can sound sure and be wrong, and to choose a suitable tool for a job.","tr":"Bu derste bir yapay zekâ aracının neden emin görünüp yanılabileceğini açıklamayı ve bir iş için uygun aracı seçmeyi öğreneceksin.","fa":"در این درس یاد می‌گیری توضیح بدهی چرا ابزار هوش مصنوعی ممکن است با اطمینان جواب بدهد و باز هم اشتباه کند، و برای هر کار ابزار مناسب را انتخاب کنی."},"hook":{"en":"Ask an AI tool about your own product and it may answer at once, in perfect English, and be wrong. Once you know why, you know what to check and which tool to choose.","tr":"Bir yapay zekâ aracına kendi ürününü sor; hemen, kusursuz İngilizceyle yanıt verip yine de yanılabilir. Nedenini bilirsen neyi kontrol edeceğini ve hangi aracı seçeceğini de bilirsin.","fa":"از ابزار هوش مصنوعی درباره‌ی محصول خودت بپرس؛ ممکن است فوری و با انگلیسی بی‌نقص جواب بدهد و با این حال اشتباه کند. وقتی دلیلش را بدانی، می‌دانی چه چیزی را بررسی کنی و کدام ابزار را انتخاب کنی."},"stats":[{"label":{"en":"Minutes","tr":"Dakika","fa":"دقیقه"},"value":"20"},{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"5"},{"label":{"en":"Tasks","tr":"Görev","fa":"تمرین"},"value":"3"}],"points":[{"head":{"en":"How a tool makes an answer","tr":"Bir araç yanıtı nasıl üretir","fa":"ابزار چطور جواب را می‌سازد"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"A text assistant learned from a huge amount of text. It learned which words usually come next. So it writes your answer one small piece at a time, and each time it picks a likely next word. Usually it isn't looking up a fact.","tr":"Metin asistanı çok büyük miktarda metinden öğrenmiştir. Hangi kelimelerin genelde ardından geldiğini öğrenmiştir. Yanıtını küçük parçalarla yazar ve her seferinde olası bir sonraki kelimeyi seçer. Çoğu zaman bir bilgiye bakmıyordur.","fa":"دستیار متنی از حجم خیلی زیادی متن یاد گرفته است. یاد گرفته معمولاً بعد از هر کلمه چه کلمه‌ای می‌آید. پس جوابت را تکه‌تکه می‌نویسد و هر بار یک کلمه‌ی محتمل بعدی را انتخاب می‌کند. معمولاً دنبال واقعیتی نمی‌گردد."},"steps":[{"en":"A common fact: many texts say it, so the likely words are usually right.","tr":"Yaygın bir bilgi: Birçok metin bunu söyler, bu yüzden olası kelimeler genelde doğrudur.","fa":"اگر چیزی رایج باشد، متن‌های زیادی از آن حرف زده‌اند، پس کلمه‌های محتمل معمولاً درست‌اند.","ex":"The capital of France is... Paris."},{"en":"There are many likely words, so the same question can get a different answer.","tr":"Olası kelime çoktur, bu yüzden aynı soru farklı bir yanıt alabilir.","fa":"کلمه‌های محتمل زیادند، پس ممکن است همان سؤال هر بار جواب متفاوتی بگیرد."}],"tip":{"en":"Some tools also search the web or read your file. Then they have real text, but they can still make mistakes.","tr":"Bazı araçlar web'de arama da yapar ya da dosyanı okur. O zaman gerçek bir metinleri olur, ama yine de hata yapabilirler.","fa":"بعضی ابزارها در وب هم می‌گردند یا فایلت را می‌خوانند. آن وقت متن واقعی دارند، ولی باز هم ممکن است اشتباه کنند."}},{"head":{"en":"Why it sometimes invents things","tr":"Neden bazen uydurur","fa":"چرا گاهی چیزی را از خودش می‌سازد"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"Now ask about something rare, such as your own product. Few texts say it, but the next word must still come. Training also rewards giving an answer more than saying \"I don't know\". So it writes what a true answer would look like.","tr":"Şimdi nadir bir şey sor, örneğin kendi ürününü. Bunu söyleyen metin azdır, ama bir sonraki kelime yine de gelmelidir. Eğitim de \"bilmiyorum\" demekten çok yanıt vermeyi ödüllendirir. Bu yüzden doğru bir yanıtın neye benzeyeceğini yazar.","fa":"حالا درباره‌ی چیزی کمیاب بپرس، مثلاً محصول خودت. متن‌های کمی از آن حرف زده‌اند، ولی ابزار باید کلمه‌ی بعدی را بنویسد. در آموزش ابزار هم جواب دادن بیشتر از گفتن «نمی‌دانم» پاداش می‌گیرد. پس چیزی می‌نویسد که شبیه جواب درست است."},"steps":[{"en":"You give no facts. It has nothing to use, so it guesses.","tr":"Bilgi vermiyorsun. Kullanacak bir şeyi yok, bu yüzden tahmin ediyor.","fa":"اگر اطلاعاتی ندهی، ابزار چیزی برای استفاده ندارد و حدس می‌زند.","ex":"You: Warranty on our Nova printer? Tool: 24 months."},{"en":"You give the fact and say \"use only this\". Now it has real text.","tr":"Bilgiyi veriyor ve \"use only this\" diyorsun. Artık gerçek bir metni var.","fa":"اگر اطلاعات را بدهی و بگویی «⁨use only this⁩»، ابزار متن واقعی در دست دارد.","ex":"You: Our sheet says 12 months. Use only this. Tool: 12 months."},{"en":"Both answers sound just as sure. A sure tone is not proof.","tr":"İki yanıt da aynı ölçüde emin görünür. Emin bir üslup kanıt değildir.","fa":"هر دو جواب به یک اندازه مطمئن به نظر می‌رسند. لحن مطمئن دلیل درستی نیست.","ex":"So check it against your source."}],"tip":{"en":"This has real costs. In 2023 a US court fined lawyers who filed court cases that an AI tool had invented. The person who sends it is responsible.","tr":"Bunun gerçek bedelleri var. 2023'te bir ABD mahkemesi, bir yapay zekâ aracının uydurduğu davaları sunan avukatlara para cezası verdi. Sorumlu olan, gönderen kişidir.","fa":"این اشتباه‌ها هزینه‌ی واقعی دارند. در سال ۲۰۲۳ دادگاهی در آمریکا چند وکیل را جریمه کرد، چون پرونده‌هایی به دادگاه داده بودند که یک ابزار هوش مصنوعی از خودش ساخته بود. مسئولیت با کسی است که آن را می‌فرستد."}},{"head":{"en":"Three kinds of tool, six names","tr":"Üç tür araç, altı ad","fa":"سه نوع ابزار، شش اسم"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"steps":[{"en":"A text assistant writes, explains and answers in a chat.","tr":"Metin asistanı sohbette yazar, açıklar ve yanıt verir.","fa":"دستیار متنی در چت می‌نویسد، توضیح می‌دهد و جواب می‌دهد.","ex":"ChatGPT and Claude: general. Gemini: Google. Copilot: Microsoft."},{"en":"AI search gives an answer with links to its sources.","tr":"Yapay zekâlı arama, kaynaklarına bağlantılarla birlikte yanıt verir.","fa":"جست‌وجوی هوش مصنوعی جوابی همراه با لینک منبع‌هایش می‌دهد.","ex":"Perplexity"},{"en":"An image maker turns your words into pictures.","tr":"Görsel üretici, kelimelerini görsele çevirir.","fa":"سازنده‌ی تصویر کلمه‌هایت را به تصویر تبدیل می‌کند.","ex":"Midjourney. ChatGPT and Gemini also make images."}]},{"head":{"en":"Choose by the job, and by where your work is","tr":"İşe ve işinin bulunduğu yere göre seç","fa":"ببین چه کاری داری و کارت کجاست، بعد انتخاب کن"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"Ask two questions: what is the job, and where is my work?","tr":"İki soru sor: İş ne, işim nerede?","fa":"از خودت دو سؤال بپرس: کارم چیست و کجا انجامش می‌دهم؟"},"steps":[{"en":"Your files are in Word and Excel: look at Copilot.","tr":"Dosyaların Word ve Excel'deyse Copilot'a bak.","fa":"اگر فایل‌هایت در ⁨Word⁩ و ⁨Excel⁩ است، سراغ ⁨Copilot⁩ برو.","ex":"If your files are in Word, try Copilot."},{"en":"Your work is in Gmail and Docs: look at Gemini.","tr":"İşin Gmail ve Docs'taysa Gemini'a bak.","fa":"اگر کارت در ⁨Gmail⁩ و ⁨Docs⁩ است، سراغ ⁨Gemini⁩ برو.","ex":"If you work in Gmail, try Gemini."},{"en":"You need links to sources: look at Perplexity.","tr":"Kaynak bağlantılarına ihtiyacın varsa Perplexity'ye bak.","fa":"اگر لینک منبع لازم داری، سراغ ⁨Perplexity⁩ برو.","ex":"If you need sources, try Perplexity."}],"tip":{"en":"No tool is best at everything, and not every tool is available in every country. Try one task on two tools if you can.","tr":"Hiçbir araç her işte en iyi değildir ve her araç her ülkede kullanılamaz. Yapabiliyorsan bir işi iki araçta dene.","fa":"هیچ ابزاری در همه‌چیز بهترین نیست و هر ابزاری در هر کشوری در دسترس نیست. اگر می‌توانی، یک کار را در دو ابزار امتحان کن."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Recommending a tool: good at, better for, if you need","tr":"Araç önermek: good at, better for, if you need","fa":"ابزار را پیشنهاد بده: ⁨good at⁩، ⁨better for⁩، ⁨if you need⁩"},"steps":[{"en":"After good at, use a verb with -ing.","tr":"good at'ten sonra -ing'li fiil kullan.","fa":"بعد از ⁨good at⁩ فعل با ‎⁨-ing⁩ بیاور.","ex":"It is good at rewriting emails."},{"en":"After better for, use a noun or -ing.","tr":"better for'dan sonra isim ya da -ing'li fiil gelir.","fa":"بعد از ⁨better for⁩ اسم یا فعل با ‎⁨-ing⁩ می‌آید.","ex":"It is better for research."},{"en":"Use if + present, then try.","tr":"if + geniş zaman, ardından try kullan.","fa":"بعد از ⁨if⁩ فعل را در زمان حال بیاور و در بخش دوم از ⁨try⁩ استفاده کن.","ex":"If you need pictures, try Midjourney."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["X is good at + -ing","Claude is good at answering questions about long documents."],["X is better for + noun","Perplexity is better for quick research."],["X works inside + place","Copilot works inside Word and Excel."],["If you need X, try Y","If you need sources, try Perplexity."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Turn a choice into a recommendation","tr":"Bir seçimi öneriye çevir","fa":"انتخاب را به پیشنهاد تبدیل کن"},"item":"Use Perplexity.\nJob: find sources for a report.","answer":"We need sources for this report, so I suggest Perplexity. It is good at finding pages we can open and check.","walk":[{"en":"Say the job first: what do you need?","tr":"Önce işi söyle: Neye ihtiyacın var?","fa":"اول کار را بگو: چه چیزی لازم داری؟"},{"en":"Name the tool with \"I suggest\".","tr":"Aracı \"I suggest\" ile söyle.","fa":"ابزار را با «⁨I suggest⁩» بگو."},{"en":"Add one reason with \"good at\".","tr":"\"good at\" ile bir neden ekle.","fa":"با «⁨good at⁩» یک دلیل اضافه کن."}],"why":{"en":"The first version only names a tool, so the reader must just trust you. The second gives the job and a reason, so the reader can decide.","tr":"İlk sürüm yalnızca aracın adını söyler, okuyucu sana güvenmek zorunda kalır. İkincisi işi ve nedeni verir, böylece okuyucu karar verebilir.","fa":"نسخه‌ی اول فقط اسم ابزار را می‌گوید و خواننده باید حرفت را قبول کند. نسخه‌ی دوم کار و دلیل را هم می‌گوید، پس خواننده خودش می‌تواند تصمیم بگیرد."}},"quick":{"prompt":"You ask a tool: \"What is the warranty on our printer?\" You give it no document. It answers \"24 months\" in perfect English. What do you do?","options":["Check the 24 months against your own sheet.","Use it, because the English is perfect.","Ask the tool the same question again."],"correct":0,"why":{"en":"It had no facts, so 24 months may be a guess. Asking again only gets more likely words.","tr":"Bilgisi yoktu, yani 24 ay bir tahmin olabilir. Yeniden sormak yalnızca yeni olası kelimeler getirir.","fa":"اطلاعاتی نداشت، پس ۲۴ ماه شاید حدس باشد. دوباره پرسیدن فقط کلمه‌های محتمل دیگری می‌آورد."}},"quickAfter":2,"remember":{"en":"It writes likely words, not checked facts, so give it your facts and check its answer. You can now explain why a sure answer can be wrong, and choose a tool for a job.","tr":"Kontrol edilmiş bilgi değil, olası kelimeler yazar; bu yüzden bilgini ver ve yanıtını kontrol et. Artık emin görünen bir yanıtın neden yanlış olabileceğini açıklayabilir ve bir iş için araç seçebilirsin.","fa":"ابزار کلمه‌های محتمل را می‌نویسد، نه واقعیت‌های بررسی‌شده؛ پس اطلاعاتت را به آن بده و جوابش را بررسی کن. حالا می‌توانی توضیح بدهی چرا جواب مطمئن هم ممکن است غلط باشد و برای هر کار ابزاری انتخاب کنی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر ⁨B2⁩"},"head":{"en":"Giving a reason: since, as, which means","tr":"Neden belirtmek: since, as, which means","fa":"دلیل آوردن: ⁨since⁩، ⁨as⁩، ⁨which means⁩"},"steps":[{"en":"Since or as can open the sentence with the reason.","tr":"since ya da as cümleyi nedenle açabilir.","fa":"با ⁨since⁩ یا ⁨as⁩ می‌توانی جمله را با دلیل شروع کنی.","ex":"As we use Gmail, Gemini fits."},{"en":"Which means adds the result of the whole idea.","tr":"which means tüm fikrin sonucunu ekler.","fa":"با ⁨which means⁩ نتیجه‌ی کل حرفت را اضافه می‌کنی.","ex":"It is paid, which means we need a budget."},{"en":"Use a comma before which means.","tr":"which means'ten önce virgül kullan.","fa":"پیش از ⁨which means⁩ ویرگول بگذار.","ex":"It lives in Word, which means no copying."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["since + reason","Since our files are in Word, I suggest Copilot."],["which means + result","It gives links, which means we can check them."]]},"body":{"en":"B2: give the reason for your recommendation with since or which means.","tr":"B2: önerinin nedenini since ya da which means ile ver.","fa":"⁨B2⁩: دلیل پیشنهادت را با ⁨since⁩ یا ⁨which means⁩ بگو."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
